// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Create Fixed Asset - Factory Equipment
// Hand edits: text/id-based inputs, state assertions after each action, result screenshots, wide viewport,
// login fallback. Re-running `npm run gen` would overwrite them.
import { test, expect } from "../../../../core/fixtures/index";
import { uniqueName } from "../../../../core/utils/RandomDataGenerator";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-create-fixed-asset-factory-equipment";

// Keep a screenshot of the finished screen (a step's own screenshot is taken BEFORE its action).
async function resultShot(page: Page, file: string) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: SHOT_DIR + "/" + file });
}

// Open a report from the top menu. The Reporting menu (and its "+" overflow) is not always laid out the same
// way, so open whatever is needed to make the report entry visible, then return it.
async function openReport(page: Page, xmlid: string): Promise<Locator> {
  const item = page.locator('[data-menu-xmlid="' + xmlid + '"]').first();
  if (!(await item.isVisible().catch(() => false))) {
    const more = page.locator(".o_menu_sections_more button").first();
    if (await more.isVisible().catch(() => false)) await more.click();
  }
  if (!(await item.isVisible().catch(() => false))) {
    await page.locator(".dropdown-toggle, .dropdown-item").filter({ hasText: /^Reporting$/ }).first().click();
  }
  await item.waitFor({ state: "visible", timeout: 45000 });
  return item;
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

const ASSET = uniqueName("Factory Equipment - New Machine");

test.describe("Finance: Create Fixed Asset - Factory Equipment @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Create Fixed Asset - Factory Equipment", async ({ page }) => {
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    await test.step("01. Open the Accounting Module", async () => {
      const loc = page.locator('[data-menu-xmlid="account_accountant.menu_accounting"]').first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-01.png");
      await loc.click();
    });

    await test.step("02. Open Accounting Menu", async () => {
      const loc = page.locator('[data-menu-xmlid="account.menu_finance_entries"]').first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-02.png");
      await loc.click();
    });

    await test.step("03. Assets", async () => {
      const loc = page.locator('[data-menu-xmlid="account_asset.menu_action_account_asset_form"]').first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-03.png");
      await loc.click();
      await expect(page.locator(".o_list_view, .o_kanban_view").first(), "Assets list opened").toBeVisible({ timeout: 30000 });
      await resultShot(page, "step-03-result.png");
    });

    await test.step("04. New", async () => {
      const loc = page.getByRole("button", { name: "New", exact: true }).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-04.png");
      await loc.click();
      await expect(page.locator(".o_form_view"), "new asset form opened").toBeVisible({ timeout: 30000 });
      await resultShot(page, "step-04-result.png");
    });

    await test.step("05. Enter Asset Name", async () => {
      const loc = page.locator("#name_0").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-05.png");
      await loc.fill(ASSET);
      await expect(loc).toHaveValue(ASSET);
      await resultShot(page, "step-05-result.png");
    });

    await test.step("06. Select Asset Model", async () => {
      const loc = page.locator("#model_id_0").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-06.png");
      await loc.fill("Factory Equipments");
      const opt = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: "Factory Equipments" }).first();
      await opt.waitFor({ state: "visible", timeout: 15000 });
      await opt.click();
      await expect(loc, "asset model selected").toHaveValue(/Factory Equipments/i);
      // The model fills in the duration and the three accounts.
      for (const [field, code] of [["account_asset_id", "11010170"], ["account_depreciation_id", "11020170"], ["account_depreciation_expense_id", "72090050"]]) {
        await expect(page.locator(".o_field_widget[name=" + field + "] input"), "model fills in account " + code).toHaveValue(new RegExp(code), { timeout: 15000 });
      }
      await resultShot(page, "step-06-result.png");
    });

    await test.step("07. Set Original Value to 100000", async () => {
      const loc = page.locator("#original_value_0").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-07.png");
      await loc.fill("100000");
      await loc.press("Tab");
      await expect(loc).toHaveValue(/100,?000/);
      await resultShot(page, "step-07-result.png");
    });

    await test.step("08. Confirm", async () => {
      const loc = page.locator(".o_statusbar_buttons button").filter({ hasText: /^Confirm$/ }).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-08.png");
      await loc.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "asset is now Running").toContainText("Running", { timeout: 30000 });
      await resultShot(page, "step-08-result.png");
    });

    await test.step("09. Open More Menu (before Trial Balance)", async () => {
      // On a wide window every menu entry is already visible, so there may be no "+" to click.
      const more = page.locator(".o_menu_sections_more button").first();
      const target = (await more.isVisible({ timeout: 3000 }).catch(() => false)) ? more : page.locator(".o_menu_sections").first();
      await shot(page, target, "step-09.png");
    });

    await test.step("10. Trial Balance", async () => {
      const loc = await openReport(page, "account_reports.menu_action_account_report_coa");
      await shot(page, loc, "step-10.png");
      await loc.click();
      await expect(page, "Trial Balance opened").toHaveTitle(/Trial Balance/);
      await page.locator("table tbody tr").first().waitFor({ state: "visible", timeout: 30000 });
      await resultShot(page, "step-10-result.png");
    });

    await test.step("11. Open Report Options (Trial Balance)", async () => {
      const loc = page.locator("#filter_extra_options button.dropdown-toggle").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-11.png");
      await loc.click();
      await expect(page.locator("#filter_extra_options .filter_show_draft_hook")).toBeVisible();
      await resultShot(page, "step-11-result.png");
    });

    await test.step("12. Include Draft Entries (Trial Balance)", async () => {
      const loc = page.locator("#filter_extra_options .filter_show_draft_hook").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-12.png");
      await loc.click();
      await expect(page.locator("#filter_extra_options button.dropdown-toggle"), "Include Draft Entries applied").toContainText("With Draft Entries", { timeout: 30000 });
      await resultShot(page, "step-12-result.png");
    });

    await test.step("13. Check Trial Balance - Depreciation Provision", async () => {
      const exp = page.locator("tr").filter({ hasText: "72090050" }).first();
      const prov = page.locator("tr").filter({ hasText: "11020170" }).first();
      await expect(exp, "Depreciation Expense account in the Trial Balance").toBeVisible({ timeout: 30000 });
      await expect(prov, "Provision for Depreciation account in the Trial Balance").toBeVisible();
      await shot(page, prov, "step-13.png");
    });

    await test.step("14. Open More Menu (before General Ledger)", async () => {
      const more = page.locator(".o_menu_sections_more button").first();
      const target = (await more.isVisible({ timeout: 3000 }).catch(() => false)) ? more : page.locator(".o_menu_sections").first();
      await shot(page, target, "step-14.png");
    });

    await test.step("15. General Ledger", async () => {
      const loc = await openReport(page, "account_reports.menu_action_account_report_general_ledger");
      await shot(page, loc, "step-15.png");
      await loc.click();
      await expect(page, "General Ledger opened").toHaveTitle(/General Ledger/);
      await page.locator("table tbody tr").first().waitFor({ state: "visible", timeout: 30000 });
      await resultShot(page, "step-15-result.png");
    });

    await test.step("16. Open Report Options (General Ledger)", async () => {
      const loc = page.locator("#filter_extra_options button.dropdown-toggle").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-16.png");
      await loc.click();
      await expect(page.locator("#filter_extra_options .filter_show_draft_hook")).toBeVisible();
    });

    await test.step("17. Include Draft Entries (General Ledger)", async () => {
      const loc = page.locator("#filter_extra_options .filter_show_draft_hook").first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-17.png");
      await loc.click();
      await expect(page.locator("#filter_extra_options button.dropdown-toggle"), "Include Draft Entries applied").toContainText("With Draft Entries", { timeout: 30000 });
    });

    await test.step("18. Expand Depreciation Expense Account", async () => {
      const row = page.locator("tr.line_level_1").filter({ hasText: "72090050" }).first();
      await row.waitFor({ state: "visible", timeout: 45000 });
      const loc = row.locator("td.line_name").first();
      await shot(page, loc, "step-18.png");
      const before = await page.locator("table tbody tr").count();
      await loc.click();
      await expect.poll(() => page.locator("table tbody tr").count(), { message: "expanding should list the journal lines" }).toBeGreaterThan(before);
      await resultShot(page, "step-18-result.png");
    });

    await test.step("19. Check General Ledger - New Machine Depreciation Entry", async () => {
      // The draft depreciation line carries the asset's name.
      const loc = page.locator("tr").filter({ hasText: ASSET }).first();
      await expect(loc, "draft depreciation line for the new asset").toBeVisible({ timeout: 30000 });
      await shot(page, loc, "step-19.png");
    });

  });
});
